row('B03', 'SystemParametersInfoW', 'SPI_GETNONCLIENTMETRICS 0x29 (cbSize 0x1f8)', 'fonts = the same LOGFONTW, iBorderWidth 1, iPaddedBorderWidth 4, every other field 0', 'same', '2', 'FLEngine 0x866498, ILTools 0x6295cb8', 'NONCLIENTMETRICS', 'scroll 17, caption 22, menu 20 ... [typ]', 'partly (unwritten fields are 0)', 'reads the four fonts only (decision 0066 reading)', 'no', 'decision 0066; fields other than the fonts are undecided and written 0')
