def main(out):
    with open(out + '/capability-probes.tsv', 'w', newline='') as f:
        w = csv.writer(f, delimiter='\t'); w.writerow(H); w.writerows(R)
    with open(out + '/capability-probes.md', 'w') as f:
        f.write('| ' + ' | '.join(H) + ' |\n|' + '---|' * len(H) + '\n')
        for r in R: f.write('| ' + ' | '.join(str(c).replace('|', '/').replace('\n', ' ') for c in r) + ' |\n')
    print(len(R), 'rows')
main(sys.argv[1])
